  .top-meta{position:absolute;left:98px;top:61px;z-index:15;font-size:15px;font-weight:600;
    letter-spacing:4.2px;color:#4f5b53}
  .rail-label{position:absolute;left:44px;top:520px;width:330px;height:24px;z-index:15;
    transform:rotate(-90deg);transform-origin:left top;font-size:13px;font-weight:600;
    letter-spacing:5.1px;color:#637067;white-space:nowrap}

  /* ---------- top-right register ---------- */
  .register{position:absolute;right:-64px;top:-70px;width:270px;height:270px;z-index:4;
    border-radius:50%;border:1px solid rgba(27,38,32,.30)}
  .register .r2{position:absolute;inset:12px;border-radius:50%;border:1px solid rgba(27,38,32,.16)}
  .register .r3{position:absolute;inset:28px;border-radius:50%;background:
    conic-gradient(from 210deg,rgba(79,94,67,.18),rgba(79,94,67,0) 24%,rgba(140,159,178,.28) 50%,rgba(140,159,178,.06) 78%,rgba(79,94,67,.18))}
  .register .r4{position:absolute;inset:38px;border-radius:50%;background:rgba(245,242,233,.9);
    border:1px solid rgba(27,38,32,.08)}
  .register .dot{position:absolute;left:56px;top:182px;width:12px;height:12px;border-radius:50%;
    background:var(--gold);box-shadow:0 0 0 5px rgba(180,145,74,.13)}

  /* ---------- header ---------- */
  .head{position:absolute;left:96px;top:104px;width:1230px;z-index:8}
  .eyebrow{display:flex;align-items:center;gap:16px;font-size:14px;font-weight:600;
    letter-spacing:5px;color:#5C665D}
  .eyebrow .bar{width:46px;height:1px;background:rgba(27,38,32,.5)}
  .eyebrow b{color:var(--green);font-weight:700;letter-spacing:2px}
  h1{margin:20px 0 0;font-family:var(--serif);font-size:70px;line-height:1.14;
    font-weight:700;letter-spacing:1px;color:#18211c}
  .lede{margin:18px 0 0;font-size:19px;line-height:1.7;color:var(--muted);max-width:1120px}

  /* ---------- three columns ---------- */
  .cols{position:absolute;left:96px;top:396px;width:1728px;height:444px;z-index:8;
    display:grid;grid-template-columns:repeat(3,1fr);gap:28px}

  .card{position:relative;background:rgba(252,250,244,.92);border:1px solid rgba(27,38,32,.15);
    padding:28px 34px 26px;display:flex;flex-direction:column;--c:var(--green)}
  .card:before{content:"";position:absolute;left:0;top:0;right:0;height:3px;background:var(--c)}
  .card.plan{--c:var(--green)}
  .card.pending{--c:var(--gold)}
  .card.done{--c:var(--blue)}

  .card-head{display:flex;align-items:baseline;gap:14px;padding-bottom:15px;
    border-bottom:1px solid rgba(27,38,32,.16);margin-bottom:20px}
  .card-no{font-size:13px;font-weight:700;letter-spacing:2px;color:var(--c)}
  .card-head h2{margin:0;font-family:var(--serif);font-size:30px;font-weight:700;letter-spacing:1px;color:#1e2a22}
  .tag{margin-left:auto;font-size:12px;letter-spacing:2px;color:#6a736a;
    border:1px solid rgba(27,38,32,.2);padding:4px 9px;border-radius:2px;white-space:nowrap}

  .row{margin-bottom:16px}
  .row .k{font-size:12px;font-weight:700;letter-spacing:3px;color:#6a736a;margin-bottom:8px}
  .row .v{font-size:18px;line-height:1.5;color:#232d26}
  .row .v strong{color:var(--green);font-weight:700}

  .chips{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
  .chip{font-size:14px;padding:4px 10px;border-radius:2px;color:#3b4636;
    background:rgba(79,94,67,.10);border:1px solid rgba(79,94,67,.22)}
  .arrow{color:rgba(27,38,32,.30);font-size:13px}

  .drow{display:flex;align-items:baseline;justify-content:space-between;
    padding:11px 0;border-bottom:1px dashed rgba(27,38,32,.20)}
  .drow .k{font-size:15px;font-weight:600;letter-spacing:1px;color:#2b342d}
  .drow .v2{font-size:16px;font-weight:700;letter-spacing:1px;color:var(--gold)}
  .note{margin-top:auto;font-size:13.5px;line-height:1.65;color:#6a736a;
    border-left:2px solid rgba(180,145,74,.6);padding-left:12px}

  .dash{font-family:var(--serif);font-size:62px;line-height:.9;color:rgba(140,159,178,.9);margin:6px 0 16px}
  .empty p{margin:0 0 10px;font-size:19px;line-height:1.6;color:#2b342d}
  .empty small{font-size:14px;line-height:1.7;letter-spacing:.5px;color:#6a736a}
  .done-note{margin-top:auto;font-size:13px;letter-spacing:1px;color:#7b837b;
    border-top:1px solid rgba(27,38,32,.14);padding-top:12px}

  /* ---------- metrics ---------- */
  .metrics{position:absolute;left:96px;top:872px;width:1728px;height:118px;z-index:8;
    display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid rgba(27,38,32,.30)}
  .metric{padding:20px 28px 0;border-right:1px solid rgba(27,38,32,.14)}
  .metric:last-child{border-right:none}
  .metric .n{font-family:var(--serif);font-size:46px;line-height:1;font-weight:700;color:#1e2a22}
  .metric .n em{font-style:normal;font-size:20px;font-weight:700;margin-left:6px;color:var(--green);letter-spacing:1px}
  .metric .l{margin-top:10px;font-size:13px;letter-spacing:2.5px;color:#67716a}

  .bottom-rule{position:absolute;left:96px;top:1010px;width:1728px;height:1px;z-index:9;
    background:rgba(27,38,32,.26)}
  .footnote{position:absolute;left:96px;bottom:34px;z-index:12;font-size:13px;
    letter-spacing:1.6px;color:#78817a}
  .page-no{position:absolute;right:96px;bottom:32px;z-index:12;font-size:16px;font-weight:700;
    letter-spacing:3px;color:#4f5b53}
</style>
</head>
<body>
<main class="slide">
  <div class="bg-field"></div>
  <div class="dot-field dot-top"></div>
  <div class="dot-field dot-bottom"></div>
  <div class="edge-prism"><i class="p1"></i><i class="p2"></i><i class="p3"></i></div>

  <div class="gridline gl1"></div>
  <div class="gridline gl2"></div>
  <div class="gridline gl3"></div>

  <div class="top-rule"></div>
  <div class="left-rule"></div>
  <div class="rail-tick t1"></div>
  <div class="rail-tick t2"></div>
  <div class="rail-tick t3"></div>

  <div class="top-meta">镜桥产品体验日方案 · 状态区分</div>
  <div class="rail-label">STATUS REGISTER · PLAN / PENDING / DONE</div>

  <div class="register">
    <div class="r2"></div>
    <div class="r3"></div>
    <div class="r4"></div>
    <div class="dot"></div>
  </div>

  <header class="head">
    <div class="eyebrow"><b>06</b><span class="bar"></span>状态区分</div>
    <h1>计划、待确认与已完成的区分</h1>
    <p class="lede">依据附件资料整理，仅区分资料中可确认的三种状态；未记载事项留空标注，不作任何推断。</p>
  </header>

  <section class="cols">
    <article class="card plan">
      <div class="card-head">
        <span class="card-no">01</span>
        <h2>计划中</h2>
        <span class="tag">方案已写明</span>
      </div>
      <div class="row">
        <div class="k">五步流程</div>
        <div class="chips">
          <span class="chip">签到</span><span class="arrow">→</span>
          <span class="chip">任务说明</span><span class="arrow">→</span>
          <span class="chip">分组体验</span><span class="arrow">→</span>
          <span class="chip">问题记录</span><span class="arrow">→</span>
          <span class="chip">汇总复盘</span>
        </div>
      </div>
      <div class="row">
        <div class="k">分组体验</div>
        <div class="v"><strong>7 组 × 26 分钟</strong> 同时或分批轮转</div>
      </div>
      <div class="row">
        <div class="k">岗位分工</div>
        <div class="chips">
          <span class="chip">主持</span>
          <span class="chip">引导</span>
          <span class="chip">技术支持</span>
          <span class="chip">记录</span>
        </div>
      </div>
    </article>

    <article class="card pending">
      <div class="card-head">
        <span class="card-no">02</span>
        <h2>待确认</h2>
        <span class="tag">尚无定值</span>
      </div>
      <div class="drow"><span class="k">日期</span><span class="v2">尚未确定</span></div>
      <div class="drow"><span class="k">场地</span><span class="v2">尚未确定</span></div>
      <div class="drow"><span class="k">实际预算</span><span class="v2">尚未确定</span></div>
      <div class="note">以上三项资料中均标注为尚未确定，不得自行填入；须以确认后的信息替换。</div>
    </article>

    <article class="card done">
      <div class="card-head">
        <span class="card-no">03</span>
        <h2>已完成</h2>
        <span class="tag">无记载</span>
      </div>
      <div class="empty">
        <div class="dash">—</div>
        <p>资料未记载任何已完成事项</p>
        <small>此处不作推断，也不补写完成结论。</small>
      </div>
      <div class="done-note">若后续确认完成情况，再在本栏补充。</div>
    </article>
  </section>

  <section class="metrics">
    <div class="metric"><div class="n">84<em>人</em></div><div class="l">邀请名额</div></div>
    <div class="metric"><div class="n">7<em>组</em></div><div class="l">体验分组</div></div>
    <div class="metric"><div class="n">26<em>分钟</em></div><div class="l">每组体验时长</div></div>
    <div class="metric"><div class="n">9<em>项</em></div><div class="l">反馈问题</div></div>
  </section>

  <div class="bottom-rule"></div>
  <div class="footnote">资料为虚构测评材料，所有数值为测试构造值</div>
  <div class="page-no">6 / 6</div>
</main>
</body>
</html>
【指令】“计划中”栏的分组体验条目删除“同时或分批轮转”，改为“7 组 × 26 分钟”。其余保持：待确认仅日期、场地、实际预算；已完成栏保持“资料未记载任何已完成事项，此处不作推断”。
